/* Two-point horizontal bridge authoring with transient previews and one undo. */
(function(){'use strict';
const B=window.KERN_BRIDGES,S=window.KERN_SHAPES;let draft=null,hover=null,proposal=null,width=1.5;
const stop=e=>{e.preventDefault();e.stopImmediatePropagation();},scope=()=>currentBuilding().id+':'+floorId,paused=e=>isTypingTarget(e?.target)||window.KERN_WORKSPACE?.isHome?.()||window.KERN_EXPLORER?.active||e?.isComposing||e?.target?.closest?.('dialog,[role=menu],[role=listbox],.toolbar-popover')||document.querySelector('dialog[open]');
function allowed(fid){return !!model.floors[fid]&&fid===floorId&&(!window.KERN_LAYERS||window.KERN_LAYERS.canEditFloor(fid));}
function editable(e){const r=e&&model.floors[e.floor]?.rooms.find(r=>r.id===e.room);return !!r&&allowed(e.floor)&&canEdit(r)&&(!window.KERN_LAYERS||window.KERN_LAYERS.available('rooms',r.id,e.floor));}
function cancel(paint=false){const changed=!!draft||!!proposal;draft=null;hover=null;proposal=null;if(paint&&changed)draw();}
function fresh(){if(draft&&(draft.scope!==scope()||draft.model!==JSON.stringify(model))){cancel();return false;}return true;}
function previewBridge(hit){if(!hit||!allowed(hit.floor))return{valid:false,error:'Enable editing and visibility on the drawing floor first',reason:'Enable editing and visibility on the drawing floor first'};if(!fresh())return{valid:false,error:'The building changed; choose the first floor again'};hover=hit;if(!draft)return{valid:false,error:'Bridge: click the first room floor'};const q=B.candidate(model,hit.floor,draft.endpoint,hit.p,width,{z:hit.z});if(q.valid&&q.endpoints.some(e=>!editable(e)))Object.assign(q,{valid:false,reason:'Show and unlock both room floors before adding a bridge'});proposal={...q,scope:scope(),error:q.valid?null:q.reason};return proposal;}
function click(hit){if(!hit||!allowed(hit.floor)){notify('Enable editing and visibility on the drawing floor first');return false;}if(!fresh()){notify('The building changed; choose the first floor again');return false;}if(!draft){const endpoint=B.endpoint(model,hit.floor,hit.p,hit.z);if(!endpoint||!editable(endpoint)){notify('Choose a visible, editable room floor for the bridge end');return false;}draft={endpoint,scope:scope(),model:JSON.stringify(model)};hover=hit;proposal=null;draw();notify('Bridge: choose the other floor · both ends must have the same elevation');return true;}
 const q=previewBridge(hit);if(!q.valid){notify(q.error);draw();return false;}let checked;try{checked=B.checkClearance(q);}catch{notify('This gap could not form a clear bridge; choose different endpoints');return false;}if(!checked.valid){proposal={...checked,error:checked.reason};notify(checked.reason);draw();return false;}if(floor().rooms.length>=300||floor().doors.length+q.doors.length>600){notify('This floor has reached its object limit');return false;}const r=clone(q.room),oldId=r.id;r.id=uniqueId('bridge-');const doors=q.doors.map(d=>({...clone(d),id:uniqueId('d'),a:d.a===oldId?r.id:d.a,b:d.b===oldId?r.id:d.b}));cancel();setTool('select');commit(()=>{floor().rooms.push(r);floor().doors.push(...doors);setSelection({rooms:[r.id]});});notify('Bridge added · '+width.toFixed(2)+' m wide · Undo restores both endpoints');return true;
}
function start(){const off=tool==='bridge';resetTransient(true);setTool(off?'select':'bridge');if(!off){setSelection();render();notify('Bridge: click two room floors at the same elevation');}}
function handleKey(e){if(paused(e))return false;const key=String(e.key).toLowerCase();if((key==='c'||e.code==='KeyC')&&e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!e.altKey){stop(e);if(!e.repeat)start();return true;}if(key==='escape'&&tool==='bridge'&&!e.ctrlKey&&!e.metaKey&&!e.altKey){stop(e);cancel();setTool('select');return true;}return false;}
const button=document.createElement('button');button.id='tool-bridge';button.textContent='Bridge';button.title='Shift+C · Add a bridge across a gap';button.setAttribute('aria-keyshortcuts','Shift+C');$('tool-connect').after(button);button.onclick=start;
function sync(){if(draft&&!fresh())proposal=null;button.setAttribute('aria-pressed',String(tool==='bridge'));let panel=$('bridge-create-settings');if(tool!=='bridge'){panel?.remove();return;}if(!panel){panel=document.createElement('section');panel.id='bridge-create-settings';panel.className='height-room';panel.innerHTML='<h3>Bridge</h3><label class="field"><span>Width · m</span><input id="bridge-width" type="number" min="1" max="8" step=".25"></label><p class="small">Click two room floors across one gap. Both ends must be at the same height. Clear endpoint walls gain openings.</p>';$('inspector').prepend(panel);}const input=$('bridge-width');input.value=width;input.onchange=e=>{const next=Number(e.target.value);if(!Number.isFinite(next)||next<1||next>8){e.target.value=width;notify('Bridge width must be 1–8 m');return;}width=next;if(hover&&draft)previewBridge(hover);draw();};if(window.BuildingExports?.isThreeMode?.()){document.body.classList.add('editing3d');$('inspector').hidden=false;document.querySelector('.asidehead').hidden=false;}}
const oldInspector=inspector;inspector=function(){const result=oldInspector(...arguments);sync();return result;};
const oldTool=setTool;setTool=function(value){if(value!=='bridge')cancel();return oldTool(...arguments);};
const oldReset=resetTransient;resetTransient=function(){cancel();return oldReset(...arguments);};
const oldHint=toolHint;toolHint=function(){return tool==='bridge'?(proposal?.error||proposal?.summary||(draft?'Bridge: choose the second room floor · Escape cancels':'Bridge: choose the first room floor · Shift+C')):oldHint(...arguments);};
const oldMarkup=interactionMarkup;interactionMarkup=function(){let out=oldMarkup(...arguments);if(tool!=='bridge'||!draft)return out;const a=draft.endpoint.p,sz=screenUnits(5);out+=`<g pointer-events="none"><circle cx="${a.x}" cy="${a.y}" r="${sz}" fill="#70c9e4"/>`;if(proposal?.valid)out+=`<path d="M${S.points(proposal.room).map(p=>p.join(' ')).join('L')}Z" fill="#70c9e433" stroke="#70c9e4" stroke-width="${screenUnits(2)}"/>`;else if(hover)out+=`<path d="M${a.x} ${a.y}L${hover.p.x} ${hover.p.y}" stroke="#cf8a76" stroke-width="${screenUnits(2)}" stroke-dasharray="${screenUnits(5)} ${screenUnits(3)}"/>`;return out+'</g>';};
window.addEventListener('pointerdown',e=>{if(tool!=='bridge'||window.BuildingExports?.isThreeMode?.()||e.button!==0||e.altKey||e.ctrlKey||e.metaKey||spaceHeld||preview||!e.target.closest?.('#plan'))return;stop(e);$('plan').focus({preventScroll:true});click({floor:floorId,p:point(e)});},true);
window.addEventListener('pointermove',e=>{if(tool!=='bridge'||window.BuildingExports?.isThreeMode?.()||e.altKey||spaceHeld||preview||!draft||!e.target.closest?.('#plan'))return;previewBridge({floor:floorId,p:point(e)});draw();},true);
// Keep the authoring function distinct from the editor's temporary-pan flag.

window.addEventListener('blur',()=>cancel(true));$('plan').addEventListener('pointercancel',()=>cancel(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)cancel(true);});
window.KERN_BRIDGE_UI={preview:previewBridge,click,cancel,isEditing:()=>!!draft,getDraft:()=>draft&&clone(draft.endpoint),handleKey,active:()=>tool==='bridge',get width(){return width;}};
})();
